// ─── File: TlabDemo.java ───
// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.tlab;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class TlabDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        int threads = Runtime.getRuntime().availableProcessors();
        int allocationsPerThread = 5_000_000;
        log.info(() -> "running " + threads + " threads, each allocating "
                + allocationsPerThread + " TransferMessages from its OWN TLAB");

        ExecutorService pool = Executors.newFixedThreadPool(threads);
        List<Future<Long>> futures = new ArrayList<>();
        long start = System.nanoTime();

        // Each worker allocates from its THREAD-LOCAL TLAB: lock-free pointer bumps.
        for (int t = 0; t < threads; t++) {
            futures.add(pool.submit(new AllocationWorker(allocationsPerThread)));
        }
        long totalChecksum = 0;
        for (Future<Long> f : futures) totalChecksum += f.get();
        long elapsedMs = (System.nanoTime() - start) / 1_000_000;

        pool.shutdown();
        long totalAllocs = (long) threads * allocationsPerThread;
        long cs = totalChecksum, ms = Math.max(1, elapsedMs);
        log.info(() -> "allocated " + totalAllocs + " objects in " + ms + " ms");
        log.info(() -> "throughput ≈ " + (totalAllocs / ms) + " K allocations/sec per ms"
                + " (no lock contention: each thread bumps its own TLAB pointer)");
        log.info(() -> "only TLAB REFILL touches shared Eden (atomic, rare); checksum=" + cs);
    }
}

// ─── Would be in TransferMessage.java (SMALL object → fits in a TLAB) ───
class TransferMessage {
    private final int fromId;
    private final int toId;
    private final long amountPaise; // integer paise to keep the object small
    TransferMessage(int fromId, int toId, long amountPaise) {
            this.fromId = fromId;
            this.toId = toId
            this.amountPaise = amountPaise;
    }
    long amountPaise() { return amountPaise; }
}

// ─── Would be in AllocationWorker.java (per-thread allocation burst) ───
class AllocationWorker implements java.util.concurrent.Callable<Long> {
    private final int count;
    AllocationWorker(int count) { this.count = count; }

    @Override
    public Long call() {
        long checksum = 0;
        for (int i = 0; i < count; i++) {
            // Each 'new' is a bump-the-pointer in THIS thread's TLAB: no lock.
            TransferMessage msg = new TransferMessage(i, i + 1, i * 100L);
            checksum += msg.amountPaise();   // touch it so it is not optimized away
            // msg dies immediately → reclaimed cheaply by a Minor GC
        }
        return checksum;
    }
}
